def get_axioms() -> list:
    return []


def get_vars() -> dict:
    grad = TensorVar('grad')
    log_probs = TensorVar('log_probs')
    targets = TensorVar('targets')
    input_lengths = IntArrayVar('input_lengths')
    target_lengths = IntArrayVar('target_lengths')
    neg_log_likelihood = TensorVar('neg_log_likelihood')
    log_alpha = TensorVar('log_alpha')
    return {'grad': grad, 'log_probs': log_probs, 'targets': targets, 'input_lengths': input_lengths, 'target_lengths': target_lengths, 'neg_log_likelihood': neg_log_likelihood, 'log_alpha': log_alpha}


def build_solver() -> Solver:
    s = Solver()
    s.add(*get_axioms())
    return s
